arguments.command:
cat > /tmp/git-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  Username*) echo x-access-token ;;
  Password*) echo "$GITHUB_TOKEN" ;;
  *) echo "" ;;
esac
EOF
chmod 700 /tmp/git-askpass.sh && export GIT_ASKPASS=/tmp/git-askpass.sh GIT_TERMINAL_PROMPT=0 && cd /tmp/friends-rachel && git push origin HEAD:refs/heads/friend/rachel 2>&1 | sed -E 's#(https://)[^@]*@#\1[REDACTED]@#' | tail -5 && git rev-parse HEAD && git ls-remote origin refs/heads/friend/rachel
